'use client';
import { useEffect, useState } from 'react';
export default function ProgressPage(){const [data,setData]=useState({answered:0,correct:0});useEffect(()=>{const saved=JSON.parse(localStorage.getItem('quiz-progress')??'{}') as Record<string,boolean>;const values=Object.values(saved);setData({answered:values.length,correct:values.filter(Boolean).length})},[]);const percent=data.answered?Math.round(data.correct/data.answered*100):0;return <main><header className="hero"><p className="eyebrow">Tiến độ học</p><h1>Kết quả luyện tập của bạn</h1><p className="lead">Dữ liệu được lưu trên thiết bị hiện tại.</p></header><section className="progressCards"><article><span>Câu đã làm</span><strong>{data.answered}/430</strong></article><article><span>Câu đúng</span><strong>{data.correct}</strong></article><article><span>Độ chính xác</span><strong>{percent}%</strong></article></section></main>}
